// Subscription events and disputes carry only ids, so the next steps look up the customer or the charge in Stripe.
return $input.all().map(({ json: event }) => {
  const object = event.data?.object ?? {};
  const idOf = (value) => (typeof value === 'string' ? value : value?.id ?? '');
  if (String(event.type).startsWith('customer.subscription.')) return { json: { event, lookup: 'customer', id: idOf(object.customer) } };
  if (event.type === 'charge.dispute.created') return { json: { event, lookup: 'charge', id: idOf(object.charge) } };
  return { json: { event, lookup: 'none', id: '' } };
});

// Your FluentCRM incoming webhook (FluentCRM > Settings > Incoming Webhooks). The address is its key: keep it here,
// never in a page or an app people download. It must start with https:// (http only for a site on this computer).
const WEBHOOK_URL = 'https://your-store.example/?fluentcrm=1&route=contact&hash=YOUR_WEBHOOK_HASH';

// The tag names for each state. Change any to match the tags already in your FluentCRM.
const TAGS = {
  customer: 'Customer',
  trial: 'Trial',
  trialEnding: 'Trial Ending',
  cancelled: 'Cancelled',
  refunded: 'Refunded',
  paymentFailed: 'Payment Failed',
  pastDue: 'Past Due',
  checkoutAbandoned: 'Checkout Abandoned',
  disputed: 'Disputed',
};

const [, scheme, host] = /^(https?):\/\/(\[[^\]]*\]|[^/:?#]*)/i.exec(WEBHOOK_URL.trim()) ?? [];
if (scheme?.toLowerCase() !== 'https' && !(scheme?.toLowerCase() === 'http' && ['localhost', '127.0.0.1', '[::1]'].includes(host?.toLowerCase()))) {
  throw new Error('The FluentCRM webhook address must start with https://.');
}

const text = (value) => (typeof value === 'string' && value.trim() !== '' ? value.trim() : undefined);
const list = (...names) => [...new Set(names.filter(Boolean))];

// What one event means for the contact (the same mapping as the AnyPress SDK's contactUpdateFromStripe).
function change(event, found) {
  const object = event.data?.object ?? {};
  const previous = event.data?.previous_attributes ?? {};
  const plan = text(object.metadata?.plan);
  const checkoutEmail = text(object.customer_details?.email) ?? text(object.customer_email);
  const paid = () => ({
    email: checkoutEmail,
    name: text(object.customer_details?.name),
    add: list(TAGS.customer, plan),
    remove: list(TAGS.trial, TAGS.trialEnding, TAGS.cancelled, TAGS.checkoutAbandoned),
  });
  // A customer looked up in Stripe: a deleted one has no email any more.
  const customerEmail = found && !found.deleted ? text(found.email) : undefined;
  switch (event.type) {
    case 'checkout.session.completed':
      // A delayed payment (bank debits) is still unpaid here; async_payment_succeeded follows when it clears.
      return object.mode === 'setup' || object.payment_status === 'unpaid' ? null : paid();
    case 'checkout.session.async_payment_succeeded':
      return object.mode === 'setup' ? null : paid();
    case 'checkout.session.expired':
      return object.mode === 'setup' ? null : { email: checkoutEmail, add: [TAGS.checkoutAbandoned], remove: [], optional: true };
    case 'invoice.paid':
      return { email: text(object.customer_email), add: [TAGS.customer], remove: list(TAGS.cancelled, TAGS.paymentFailed, TAGS.pastDue) };
    case 'invoice.payment_failed':
      return { email: text(object.customer_email), add: [TAGS.paymentFailed], remove: [] };
    case 'customer.subscription.updated': {
      const add = [];
      const remove = [];
      // Stripe puts the old metadata in previous_attributes: a first plan is added, a plan taken off loses its tag.
      const oldPlan = 'metadata' in previous ? text(previous.metadata?.plan) : plan;
      if (oldPlan !== plan) {
        if (plan) add.push(plan);
        if (oldPlan) remove.push(oldPlan);
      }
      if ('status' in previous) {
        if (object.status === 'past_due' || object.status === 'unpaid') add.push(TAGS.pastDue);
        if (object.status === 'active') remove.push(TAGS.pastDue, TAGS.paymentFailed);
      }
      return add.length || remove.length ? { email: customerEmail, add: list(...add), remove: list(...remove) } : null;
    }
    case 'customer.subscription.trial_will_end':
      return { email: customerEmail, add: [TAGS.trialEnding], remove: [] };
    case 'customer.subscription.deleted':
      return { email: customerEmail, add: [TAGS.cancelled], remove: list(TAGS.customer, plan, TAGS.pastDue) };
    case 'charge.refunded':
      // A partial refund leaves the customer a customer.
      return object.refunded === true
        ? { email: text(object.billing_details?.email) ?? text(object.receipt_email), add: [TAGS.refunded], remove: [TAGS.customer] }
        : null;
    case 'charge.dispute.created':
      return { email: found ? text(found.billing_details?.email) ?? text(found.receipt_email) : undefined, add: [TAGS.disputed], remove: [] };
    default:
      return null;
  }
}

// Stripe doesn't promise to send events in order, and retries a failed one later. When each contact's tags last
// changed is kept in this workflow's static data (saved on active runs), and a tag a newer event already changed is
// left alone; the event's other tags still change.
const seen = $getWorkflowStaticData('global').tagsChangedAt ?? {};

const out = [];
$input.all().forEach((item, index) => {
  const { event, lookup } = $('Find the email').itemMatching(index).json;
  const c = change(event, lookup === 'none' ? undefined : item.json);
  if (!c) return;
  if (!c.email) {
    if (c.optional) return;
    throw new Error(`Stripe's ${event.type} event has no email for this customer (a deleted Stripe customer has none).`);
  }
  const body = { email: c.email.toLowerCase() };
  const current = (tag) => typeof event.created !== 'number' || event.created >= (seen[body.email]?.[tag] ?? -Infinity);
  c.add = c.add.filter(current);
  c.remove = c.remove.filter(current);
  if (!c.add.length && !c.remove.length) return;
  if (c.name) {
    const [first, ...rest] = c.name.split(/\s+/);
    body.first_name = first;
    if (rest.length) body.last_name = rest.join(' ');
  }
  if (c.add.length) body.tags = c.add;
  if (c.remove.length) body.detach_tags = c.remove;
  out.push({ json: { url: WEBHOOK_URL.trim(), body, created: event.created }, pairedItem: { item: index } });
});
return out;

// FluentCRM answers in WordPress's JSON envelope: { success: true } when it took the update, { success: false,
// data: { message } } when it didn't. Anything else (an error page, a redirect) fails this run so it shows in
// Executions (and starts your error workflow, if you set one).
const data = $getWorkflowStaticData('global');
data.tagsChangedAt ??= {};
return $input.all().map(({ json }, index) => {
  let answer = null;
  try {
    // The HTTP node's full response puts the body under `data` when it reads it as text.
    answer = typeof json.data === 'string' ? JSON.parse(json.data) : json.data;
  } catch {}
  if (json.statusCode >= 200 && json.statusCode < 300 && answer?.success === true) {
    const { body, created } = $('Shape the update').itemMatching(index).json;
    if (typeof created === 'number') {
      const times = (data.tagsChangedAt[body.email] ??= {});
      for (const tag of [...(body.tags ?? []), ...(body.detach_tags ?? [])]) times[tag] = Math.max(created, times[tag] ?? created);
    }
    return { json: answer };
  }
  const reason = answer?.data?.message ?? answer?.message ?? 'no answer from FluentCRM; is the plugin on and the address right?';
  throw new Error(`FluentCRM did not take the contact update (${json.statusCode}: ${reason}).`);
});
